      "content": "// dsh-spring-admin-kit — host half.
// Registers the two bundled skills (EasyExcel batch import/export and the
// Thymeleaf+LayUI template safety guard) through the official runtime-skill
// API: ctx.skills.register({ name, description, content, ... }).
//
// The skills ship as SKILL.md files under ./skills/<name>/ with YAML front
// matter; we parse the front matter for the official `description` and strip
// it from the body so the model sees the same content as a filesystem skill.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const pluginRoot = dirname(fileURLToPath(import.meta.url));
const skillsRoot = join(pluginRoot, "..", "skills");

/**
 * Load a bundled SKILL.md: split YAML front matter, return
 * { name, description, content, source, whenToUse? }.
 * Throws loudly if the file or its front matter is malformed — a skill
 * that registers half-broken is worse than a plugin that fails to load.
 */
function loadBundledSkill(name) {
  const raw = readFileSync(join(skillsRoot, name, "SKILL.md"), "utf8");
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
  if (!match) throw new Error(`dsh-spring-admin-kit: ${name}/SKILL.md has no YAML front matter`);
  const [, frontMatter, body] = match;
  const fields = {};
  for (const line of frontMatter.split(/\r?\n/)) {
    const entry = /^(\w[\w-]*):\s*(.*)$/.exec(line.trim());
    if (entry) fields[entry[1]] = entry[2].trim();
  }
  if (!fields.description) throw new Error(`dsh-spring-admin-kit: ${name}/SKILL.md front matter lacks "description"`);
  return {
    name,
    description: fields.description,
    ...fields.whenToUse ? { whenToUse: fields.whenToUse } : {},
    content: body,
    source: `plugin:dsh-spring-admin-kit/${name}`,
  };
}

export const inject = ["skills"];

export function apply(ctx) {
  for (const name of ["excel-batch-import-export", "thymeleaf-layui-guard"]) {
    const skill = loadBundledSkill(name);
    ctx.skills.register(skill);
    ctx.logger.info("registered skill %s", name);
  }
}
